import{a,_ as t}from"./chunks/工作台-1700.CnvaeC1D.js";import{_ as o,o as r,c as i,a2 as d}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/img/PMS%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86/%E6%96%87%E6%A1%A3%E4%B8%AD%E5%BF%83/%E7%9F%A5%E8%AF%86%E5%BA%93%E5%88%97%E8%A1%A8-1700.png",s="/newx-doc/img/PMS%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86/%E7%A7%BB%E5%8A%A8%E7%AB%AF/%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",n="/newx-doc/img/ad/zsxq_pms.png",p="/newx-doc/img/PMS%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86/%E6%A6%82%E8%A7%88/%E6%A8%A1%E5%9D%97%E5%85%B3%E7%B3%BB.svg",f=JSON.parse('{"title":"PMS 演示","description":"","frontmatter":{},"headers":[],"relativePath":"pms-preview.md","filePath":"pms-preview.md","lastUpdated":null}'),c={name:"pms-preview.md"};function h(m,e,u,_,g,b){return r(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="pms-演示" tabindex="-1">PMS 演示 <a class="header-anchor" href="#pms-演示" aria-label="Permalink to &quot;PMS 演示&quot;">​</a></h1><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><p>PMS（Project Management System，项目管理系统）用于维护企业从项目立项、迭代规划到工作项执行与知识沉淀的完整协作链路，以项目和知识库为两个业务边界，串联项目中心、知识中心两大业务域。</p><h3 id="_1-1-pms-管理后台" tabindex="-1">1.1 PMS 管理后台 <a class="header-anchor" href="#_1-1-pms-管理后台" aria-label="Permalink to &quot;1.1 PMS 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：&quot;PMS 项目管理&quot;下的「项目中心」「知识中心」</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>pms</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><p>项目中心的页面路由以 <code>/pms/pm</code> 开头，知识中心的页面路由以 <code>/pms/kb</code> 开头。菜单与路由的对应关系如下：</p><p><img src="'+a+'" alt="管理后台 - 项目中心"></p><p><img src="'+l+'" alt="管理后台 - 知识中心"></p><h3 id="_1-2-pms-后端" tabindex="-1">1.2 PMS 后端 <a class="header-anchor" href="#_1-2-pms-后端" aria-label="Permalink to &quot;1.2 PMS 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-pms</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-pms</code> 服务</li></ul><h3 id="_1-3-pms-移动端" tabindex="-1">1.3 PMS 移动端 <a class="header-anchor" href="#_1-3-pms-移动端" aria-label="Permalink to &quot;1.3 PMS 移动端&quot;">​</a></h3><p>PMS 提供 uni-app 移动端，项目、迭代、工作项、知识库和文档都可以在手机上处理，详见 <a href="./pms/mobile">《移动端 PMS》</a>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a> 的 <code>src/pages-pms</code> 目录</li></ul><p><img src="'+s+'" alt="移动端"></p><h2 id="_2-pms-启动" tabindex="-1">2. PMS 启动 <a class="header-anchor" href="#_2-pms-启动" aria-label="Permalink to &quot;2. PMS 启动&quot;">​</a></h2><p>参见 <a href="./pms/build">《PMS 手册 —— 功能开启》</a> 文档，一般 3 分钟就可以启动完成。</p><h2 id="_3-pms-交流" tabindex="-1">3. PMS 交流 <a class="header-anchor" href="#_3-pms-交流" aria-label="Permalink to &quot;3. PMS 交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+n+'" alt="交流群"></p><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p>主要分为 2 个业务域：项目中心、知识中心。</p><p>业务以项目和知识库为中心：项目创建后自动初始化成员、工作项状态和看板列，敏捷项目再按「<strong>待规划 → 迭代 → 工作项 → 评论/动态/工时</strong>」推进执行；知识库创建后可套用模板生成默认文档，再按「<strong>知识库 → 文件夹 → 文档 → 权限与协作</strong>」沉淀资料。</p><p><img src="'+t+'" alt="PMS 功能列表"></p><h3 id="_4-1-项目中心" tabindex="-1">4.1 项目中心 <a class="header-anchor" href="#_4-1-项目中心" aria-label="Permalink to &quot;4.1 项目中心&quot;">​</a></h3><p>项目中心围绕「<strong>项目 → 迭代 → 工作项 → 协作记录</strong>」组织项目执行过程：</p><ul><li><strong>工作台</strong>：展示当前用户负责的工作项和迭代，提供需求、任务、缺陷和迭代的数量统计，并支持按项目、标题或编号、状态、优先级、迭代和截止日期筛选。</li><li><strong>我的项目</strong>：按全部项目、我负责的和我参与的查看项目，支持新建项目、个人分组、星标、项目设置、归档和移入回收站。</li><li><strong>项目详情</strong>：展示项目概况、待规划看板、甘特图、迭代和项目工时；项目管理员可以维护项目资料、成员和公告。</li><li><strong>工作项协作</strong>：支持需求、任务和缺陷，维护负责人、参与人、迭代、状态、优先级、标签、截止日期、评论、动态、工时和子工作项，并提供看板、拖拽排序、导入和导出。</li></ul><h3 id="_4-2-知识中心" tabindex="-1">4.2 知识中心 <a class="header-anchor" href="#_4-2-知识中心" aria-label="Permalink to &quot;4.2 知识中心&quot;">​</a></h3><p>知识中心以知识库为边界，围绕「<strong>知识库 → 文件夹 → 文档 → 权限与协作</strong>」沉淀项目资料：</p><ul><li><strong>知识库管理</strong>：创建知识库、选择知识库模板、维护个人分组、成员和公开状态；知识库管理员可以维护知识库资料。</li><li><strong>文档管理</strong>：在目录树中新增文件夹、富文本和文件，支持编辑、上传、预览、移动、标签和目录层级维护。</li><li><strong>权限与协作</strong>：按知识库公开范围和内容协作权限控制访问，支持成员或部门协作者、评论、回复、点赞、内部分享和公开分享链接。</li><li><strong>个人使用记录</strong>：提供我的关注、最近使用、文档搜索和最近删除；回收站支持预览、恢复和彻底删除，过期记录由定时任务清理。</li></ul><h2 id="_5-表结构" tabindex="-1">5. 表结构 <a class="header-anchor" href="#_5-表结构" aria-label="Permalink to &quot;5. 表结构&quot;">​</a></h2><p>PMS 共 <strong>33</strong> 张表，表名统一以 <code>pms_</code> 为前缀。</p><p><img src="'+p+'" alt="PMS 全表关系"></p><table tabindex="0"><thead><tr><th>模块</th><th>子前缀</th><th>表数量</th><th>核心职责</th></tr></thead><tbody><tr><td>项目中心</td><td><code>pms_project*</code>、<code>pms_iteration</code>、<code>pms_work_item*</code></td><td>17</td><td>项目、成员、分组、收藏、公告、模板、迭代，以及工作项、状态、看板、标签、评论、动态和工时</td></tr><tr><td>知识中心</td><td><code>pms_knowledge_*</code></td><td>16</td><td>知识库、成员、分组、模板、文件夹、文档、内容权限、互动、分享、使用记录和回收站</td></tr></tbody></table><h3 id="_5-1-项目中心" tabindex="-1">5.1 项目中心 <a class="header-anchor" href="#_5-1-项目中心" aria-label="Permalink to &quot;5.1 项目中心&quot;">​</a></h3><p>项目是项目中心的<strong>业务数据边界</strong>，迭代和工作项通过 <code>project_id</code> 归属项目；工作项还可以通过 <code>iteration_id</code>、<code>parent_id</code> 和 <code>related_requirement_id</code> 建立迭代、父子工作项以及需求与缺陷的关联。</p><p>项目按「<strong>创建项目 → 初始化状态与看板 → 维护成员和公告 → 规划迭代 → 执行工作项</strong>」推进。项目详情中的概况、待规划看板、甘特图和工时汇总，均根据项目、迭代、工作项和工时记录<strong>实时查询</strong>，不建立展示快照表。</p><ul><li><a href="./pms/pm/project">《【项目中心】工作台与项目管理》</a></li><li><a href="./pms/pm/project/detail">《【项目中心】项目详情与迭代》</a></li><li><a href="./pms/pm/work-item">《【项目中心】工作项与协作》</a></li></ul><h3 id="_5-2-知识中心" tabindex="-1">5.2 知识中心 <a class="header-anchor" href="#_5-2-知识中心" aria-label="Permalink to &quot;5.2 知识中心&quot;">​</a></h3><p>知识库是知识中心的<strong>业务数据边界</strong>。知识库、文件夹和文档通过 <code>library_id</code>、<code>parent_id</code> 和 <code>folder_id</code> 组成树形内容；知识库成员、内容权限成员、评论、点赞、分享、关注和浏览记录分别保存协作关系。</p><p>删除采用「<strong>标记回收 + 延迟清理</strong>」：删除的内容先写入 <code>pms_knowledge_recycle_record</code>，默认保留 30 天，恢复或彻底删除时再由对应业务服务处理。</p><ul><li><a href="./pms/kb/library">《【知识中心】知识库管理》</a></li><li><a href="./pms/kb/document">《【知识中心】文档与协作》</a></li></ul>',42)])])}const A=o(c,[["render",h]]);export{f as __pageData,A as default};
